"""Bounded Office retrieval using only advertised native tools and actual hits."""


def run(ctx,inputs):
    try:
        query=inputs['query']
        if not isinstance(query,str) or not query.strip():raise ValueError('nonempty query required')
        available={t['name'] for t in ctx.available_tools()}
        paths=inputs.get('paths');pattern=inputs.get('file_pattern')
        if paths is None and pattern:
            r=ctx.call('glob',{'pattern':pattern})
            if not r.get('accepted'):return {'status':'blocked','outputs':{},'detail':r.get('error','glob failed')}
            paths=r['data']
        maximum=min(4,max(1,inputs.get('max_windows',3)))
        pages=min(4,max(1,inputs.get('max_pages',2)))
        before=min(4000,max(0,inputs.get('before',1000)));after=min(8000,max(500,inputs.get('after',3500)))
        args={'pattern':query}
        if paths is not None:args['paths']=paths
        hits=[];complete=False;cursor=None;seen=set()
        for _ in range(pages):
            if ctx.remaining_calls()<=0:break
            if 'grep_page' in available:
                call={**args,'limit':40}
                if cursor is not None:call['cursor']=cursor
                r=ctx.call('grep_page',call)
                if not r.get('accepted'):return {'status':'blocked','outputs':{},'detail':r.get('error','search failed')}
                data=r['data'];hits.extend(data['hits']);complete=data['complete'];cursor=data.get('next_cursor')
                if complete or not cursor or cursor in seen or len(hits)>=maximum:break
                seen.add(cursor)
            else:
                r=ctx.call('grep',args)
                if not r.get('accepted'):return {'status':'blocked','outputs':{},'detail':r.get('error','search failed')}
                hits.extend(r['data']);complete=len(r['data'])<40;break
        windows=[];read_seen=set();read_errors=[]
        for hit in hits:
            if len(windows)>=maximum or ctx.remaining_calls()<=0:break
            path,offset=hit['path'],hit['offset'];key=(path,offset)
            if key in read_seen:continue
            read_seen.add(key)
            if 'read_context' in available:
                r=ctx.call('read_context',{'path':path,'offset':offset,'before':before,'after':after})
                if not r.get('accepted'):read_errors.append(r.get('error','read_context failed'));continue
                data=r['data'];start=data['start_offset'];text=data['text']
            else:
                start=max(0,offset-before);r=ctx.call('read',{'path':path,'offset':start})
                if not r.get('accepted'):read_errors.append(r.get('error','read failed'));continue
                text=r['data']['text'][:before+after]
            if text:windows.append({'path':path,'start_offset':start,'hit_offset':offset,'text':text})
        if not windows and read_errors:return {'status':'blocked','outputs':{},'detail':str(read_errors)}
        if not windows:return {'status':'not_found' if complete and not hits else 'needs_input','outputs':{},
            'detail':'No acquired matching window; broaden query/scope or read an actual hit. Incomplete search is not proof of absence.'}
        return {'status':'ok','outputs':{'windows':windows,'search_exhausted':complete,
            'target_periods_complete':None,'table_header_bound':False,'next_cursor':cursor,
            'scope':'retrieval_window_only'}}
    except (KeyError,ValueError,TypeError) as e:return {'status':'needs_input','outputs':{},'detail':str(e)}

"""Conservative row/column extraction from supplied Treasury text; no made-up cells."""
import re
from decimal import Decimal, InvalidOperation


def cells(line):
    s=line.strip()
    if '|' in s:return [x.strip() for x in s.strip('|').split('|')]
    return [x.strip() for x in re.split(r'\t+| {2,}',s)]


def number(s):
    t=re.sub(r'(?<=\d)[*†‡]+$','',s.strip()).replace(',','')
    if re.fullmatch(r'\(?[+-]?(?:\d+(?:\.\d*)?|\.\d+)\)?',t) is None:raise ValueError('not a unique numeric cell: '+s)
    if t.startswith('(') and t.endswith(')'):t='-'+t[1:-1]
    d=Decimal(t)
    if not d.is_finite():raise ValueError('nonfinite cell')
    return str(d)


def run(ctx,inputs):
    try:
        text=inputs['text'];wanted=inputs['rows'];column=inputs['column']
        if not isinstance(text,str) or not text.strip() or not isinstance(wanted,list) or not wanted:
            raise ValueError('text and nonempty rows required')
        if any(not isinstance(x,str) or not x.strip() for x in wanted) or not isinstance(column,str):raise ValueError('row and column labels must be strings')
        raw=text.splitlines(keepends=True);offsets=[];off=0
        for line in raw:offsets.append(off);off+=len(line)
        parsed=[cells(line) for line in raw]
        norm=lambda s:' '.join(s.casefold().split())
        hints=inputs.get('header_hint','');headers=[]
        for i,row in enumerate(parsed):
            indexes=[j for j,c in enumerate(row) if norm(c)==norm(column)]
            if len(indexes)==1 and (not hints or norm(hints) in norm(' '.join(raw[max(0,i-6):i+1]))):headers.append((i,indexes[0]))
        if len(headers)!=1:raise ValueError('missing or ambiguous header; supply a tighter table window/header_hint')
        h,col=headers[0];unit=inputs.get('unit','')
        if not unit:raise ValueError('Bind the actual unit from the supplied window; use native read for missing header/unit/footnotes')
        if unit and norm(unit) not in norm(text):raise ValueError('requested unit is absent from this window')
        # Require a tight table window; repeated target labels are rejected, not merged.
        matches=[]
        for label in wanted:
            found=[]
            for i in range(h+1,len(parsed)):
                row=parsed[i]
                if len(row)<=col:continue
                if any(norm(c)==norm(label) for j,c in enumerate(row) if j!=col):
                    try:value=number(row[col])
                    except ValueError:continue
                    found.append({'row':label,'column':column,'value':value,'unit':unit,
                        'source_line':i+1,'start':offsets[i],'end':offsets[i]+len(raw[i].rstrip('\r\n')),'quote':raw[i].rstrip('\r\n')})
            if len(found)!=1:raise ValueError('missing/ambiguous row '+label+'; do not merge repeated year blocks')
            matches.append(found[0])
        return {'status':'ok','outputs':{'cells':matches,'values':[x['value'] for x in matches],
            'header':raw[h].rstrip('\r\n'),'unit':unit,'requested_rows':wanted,
            'table_header_bound':True,'target_periods_complete':True,
            'proof_scope':'requested_literal_rows_only',
            'scope':'Every requested row label matched once under this header/unit. This does not verify that your requested labels or fiscal/calendar interpretation match the question. Read the actual source if OCR is ambiguous.'}}
    except (KeyError,ValueError,TypeError,InvalidOperation) as e:return {'status':'needs_input','outputs':{},'detail':str(e)}

"""Named formulas with explicit conventions; computation, not operand provenance."""
import math
from decimal import Decimal, localcontext, ROUND_HALF_UP


def run(ctx,inputs):
    try:
        op=inputs['operation'];direction='as_supplied';formula=op
        named={'difference','ratio','percent_change','log_return','cagr','annual_log_growth'}
        if 'output_scale' in inputs:raise ValueError('output_scale is unsupported; specify output_percent explicitly')
        if op in named:
            if 'values' in inputs:raise ValueError('This operation requires named operands, not positional values')
            if op=='difference':
                raw=[inputs['from_value'],inputs['to_value']]
                if type(inputs['absolute']) is not bool:raise ValueError('absolute must be explicit boolean')
                formula='abs(to_value-from_value)' if inputs['absolute'] else 'to_value-from_value'
                direction='absolute' if inputs['absolute'] else 'to_minus_from'
            elif op=='ratio':
                raw=[inputs['denominator'],inputs['numerator']];formula='numerator/denominator';direction='numerator_over_denominator'
            else:
                raw=[inputs['base_value'],inputs['new_value']];direction='base_to_new'
                formula={'percent_change':'(new_value-base_value)/base_value','log_return':'ln(new_value/base_value)',
                         'cagr':'exp(ln(new_value/base_value)/periods)-1',
                         'annual_log_growth':'ln(new_value/base_value)/periods'}[op]
        else:raw=inputs['values']
        if not isinstance(raw,list) or not raw or len(raw)>5000:raise ValueError('1..5000 values required')
        if any(type(v) not in (str,int,float) for v in raw):raise ValueError('numeric strings/numbers required')
        with localcontext() as context:
            context.prec=50
            x=[Decimal(str(v)) for v in raw]
            if any(not v.is_finite() for v in x):raise ValueError('nonfinite operand')
            n=Decimal(len(x));mean=sum(x)/n;convention=op
            if op=='sum':v=sum(x)
            elif op=='mean':v=mean
            elif op=='symmetric_difference':
                if len(x)!=2:raise ValueError('values must be [first,second]')
                v=abs(x[1]-x[0])/((abs(x[0])+abs(x[1]))/2)
                formula='abs(second-first)/((abs(first)+abs(second))/2)';direction='absolute_symmetric'
            elif op=='share_difference':
                if len(x)!=4:raise ValueError('values must be [first_part,first_total,second_part,second_total]')
                if type(inputs.get('absolute')) is not bool:raise ValueError('absolute must be explicit boolean')
                v=x[2]/x[3]-x[0]/x[1]
                formula='second_part/second_total-first_part/first_total';direction='second_share_minus_first_share'
                if inputs['absolute']:v=abs(v);formula='abs('+formula+')';direction='absolute_share_difference'
            elif op=='median':
                a=sorted(x);mid=len(a)//2;v=a[mid] if len(a)%2 else (a[mid-1]+a[mid])/2
            elif op in {'difference','ratio','percent_change','log_return','cagr','annual_log_growth'}:
                if len(x)!=2:raise ValueError('exactly two values in [start,end] order required')
                a,b=x
                if op=='difference':v=abs(b-a) if inputs['absolute'] else b-a
                elif op=='ratio':v=b/a
                elif op=='percent_change':v=(b-a)/a
                else:
                    if a<=0 or b<=0:raise ValueError('growth operands must be positive')
                    ratio=b/a
                    if op=='log_return':v=ratio.ln()
                    else:
                        periods=Decimal(str(inputs.get('periods','0')))
                        if periods<=0:raise ValueError('positive elapsed interval count required, not observation count')
                        v=ratio.ln()/periods if op=='annual_log_growth' else (ratio.ln()/periods).exp()-1
            elif op in {'std_population','std_sample','variance_population','variance_sample'}:
                denominator=n-(1 if op.endswith('sample') else 0)
                if denominator<=0:raise ValueError('sample requires at least two observations')
                v=sum((a-mean)**2 for a in x)/denominator
                if op.startswith('std_'):v=v.sqrt()
            elif op in {'gini_population','gini_sample_adjusted'}:
                if min(x)<0 or sum(x)<=0:raise ValueError('Gini requires nonnegative values and positive sum')
                a=sorted(x);v=sum(Decimal(2*i-len(a)-1)*z for i,z in enumerate(a,1))/(n*sum(a))
                if op=='gini_sample_adjusted':
                    if n<=1:raise ValueError('sample correction requires n>1')
                    v=v*n/(n-1)
            elif op in {'correlation','ols_slope','ols_intercept'}:
                raw_y=inputs.get('other_values',[])
                if len(raw_y)!=len(x) or len(x)<2:raise ValueError('paired x/y arrays of equal length required')
                y=[Decimal(str(z)) for z in raw_y]
                if any(not z.is_finite() for z in y):raise ValueError('nonfinite y')
                my=sum(y)/n;sxx=sum((a-mean)**2 for a in x);sxy=sum((a-mean)*(b-my) for a,b in zip(x,y))
                if sxx==0:raise ValueError('zero x variance')
                slope=sxy/sxx
                if op=='ols_slope':v=slope
                elif op=='ols_intercept':v=my-slope*mean
                else:
                    syy=sum((b-my)**2 for b in y)
                    if syy==0:raise ValueError('zero y variance')
                    v=sxy/(sxx*syy).sqrt()
            elif op=='geometric_growth':
                if any(1+a<=0 for a in x):raise ValueError('growth factors must be positive')
                v=(sum((1+a).ln() for a in x)/n).exp()-1
            else:raise ValueError('unsupported named operation')
            percent=inputs.get('output_percent',False)
            if type(percent) is not bool:raise ValueError('output_percent must be boolean')
            if percent:
                if op not in {'ratio','percent_change','cagr','geometric_growth','symmetric_difference','share_difference'}:raise ValueError('percent output is not supported for this operation')
                v*=100;formula='100*('+formula+')'
            digits=inputs.get('decimals')
            if digits is not None:
                if type(digits) is not int or not 0<=digits<=18:raise ValueError('decimals must be 0..18')
                answer=format(v.quantize(Decimal(1).scaleb(-digits),rounding=ROUND_HALF_UP),'.'+str(digits)+'f')
            else:answer=format(v,'f').rstrip('0').rstrip('.') if '.' in format(v,'f') else format(v,'f')
            if answer in ('-0',''):answer='0'
            return {'status':'ok','outputs':{'value':str(v),'answer':answer,'formula':formula,'direction':direction,
                'operand_refs':inputs.get('operand_refs',[]),'periods':str(inputs.get('periods','not_applicable')),
                'unit':inputs['unit'],'output_percent':percent,'proof_scope':'local_computation_only',
                'convention':convention,'count':len(x)}}
    except (KeyError,ValueError,TypeError,ArithmeticError) as e:return {'status':'needs_input','outputs':{},'detail':str(e)}

"""Deterministic completeness check for an *explicitly specified* observation series.

This Program does not discover observations and cannot assert that the user's
requested period list matches the source question. Evidence references are
preserved for downstream use, not independently certified here.
"""
from decimal import Decimal, InvalidOperation


def run(ctx, inputs):
    try:
        required = inputs['required_periods']
        observations = inputs['observations']
        if not isinstance(required, list) or not required or len(required) > 240:
            raise ValueError('required_periods must contain 1..240 explicit period strings')
        if any(not isinstance(p, str) or not p.strip() for p in required) or len(set(required)) != len(required):
            raise ValueError('required_periods must be distinct and nonblank')
        if not isinstance(observations, list) or len(observations) > 500:
            raise ValueError('observations must be a bounded list')
        groups = {}
        for obs in observations:
            if not isinstance(obs, dict) or not {'period','value','unit','source_ref'} <= obs.keys():
                raise ValueError('each observation needs period, value, unit and source_ref')
            p, unit = obs['period'], obs['unit']
            if p not in required or not isinstance(unit, str) or not unit.strip():
                raise ValueError('observation period is not requested or unit is missing')
            v = Decimal(str(obs['value']).replace(',',''))
            if not v.is_finite():
                raise ValueError('observation is nonfinite')
            ref = obs['source_ref']
            if not isinstance(ref, dict) or not isinstance(ref.get('result_id'), str) or not isinstance(ref.get('path'), list):
                raise ValueError('source_ref must reference a real previously obtained result')
            groups.setdefault(p, []).append({'period': p, 'value': str(v), 'unit': unit, 'source_ref': ref})
        aligned, missing, conflicts = [], [], []
        for p in required:
            rows = groups.get(p, [])
            if not rows:
                missing.append(p);continue
            signatures = {(r['value'], r['unit']) for r in rows}
            if len(signatures) != 1:
                conflicts.append(p);continue
            aligned.append(rows[0])
        units = {r['unit'] for r in aligned}
        if len(units) > 1:
            conflicts.extend(p for p in required if p in groups and p not in conflicts)
        conflicts = list(dict.fromkeys(conflicts))
        complete = not missing and not conflicts and len(aligned) == len(required)
        return {'status':'ok','outputs':{
            'complete':complete,'required_periods':required,'observed_periods':[p for p in required if p in groups],
            'missing_periods':missing,'conflicting_periods':conflicts,
            'aligned_observations':aligned if not conflicts else [],
            'matched_count':len(aligned),'expected_count':len(required),
            'proof_scope':'explicit_period_bookkeeping_only',
            'note':'No source text was read here. Period semantics, quoted values, and referenced files must be checked in the actual task.'}}
    except (KeyError,ValueError,TypeError,InvalidOperation) as exc:
        return {'status':'needs_input','outputs':{},'detail':str(exc)}

"""Treasury-specific exact local transforms with explicit conventions.

Cannot identify a table, currency orientation, or task target by itself.
"""
from decimal import Decimal, localcontext, ROUND_HALF_UP
import re

SCALES={'dollars':Decimal(1),'thousands_of_dollars':Decimal(1000),
        'millions_of_dollars':Decimal(1000000),'billions_of_dollars':Decimal(1000000000)}


def run(ctx,inputs):
    try:
        op=inputs['operation']
        with localcontext() as c:
            c.prec=44
            if op=='unit_scale':
                source=inputs['source_unit'];target=inputs['target_unit']
                if source not in SCALES or target not in SCALES:raise ValueError('unsupported unit direction')
                x=Decimal(str(inputs['value']).replace(',',''));y=x*SCALES[source]/SCALES[target]
                rule=f'{source}->{target}';unit=target
            elif op=='price_32nds':
                if inputs.get('quote_basis')!='thirty_seconds':raise ValueError('source table must state quote basis as 32nds')
                raw=str(inputs['quote']).strip();m=re.fullmatch(r'(\d{1,3})\.(\d{1,2})',raw)
                if not m:raise ValueError('price quote must be an integer part and 0..31 32nd ticks')
                whole,ticks=map(int,m.groups())
                if not 0<=ticks<=31:raise ValueError('32nd ticks out of range')
                y=Decimal(whole)+Decimal(ticks)/Decimal(32)
                rule='integer + ticks/32';unit='price_points'
            elif op=='box_cox':
                x=Decimal(str(inputs['value']));lam=Decimal(str(inputs['lambda']))
                if x<=0 or not x.is_finite() or not lam.is_finite():raise ValueError('Box-Cox requires x>0 and finite lambda')
                y=x.ln() if lam==0 else ((lam*x.ln()).exp()-1)/lam
                rule='ln(x)' if lam==0 else '(x^lambda-1)/lambda';unit='transformed'
            elif op=='currency_convert':
                amount=Decimal(str(inputs['amount']));rate=Decimal(str(inputs['rate']))
                direction=inputs['rate_orientation']
                if rate<=0 or not rate.is_finite() or not amount.is_finite():raise ValueError('valid positive exchange rate required')
                if direction=='foreign_per_usd':y=amount/rate;unit='usd';rule='foreign_amount / foreign_per_usd'
                elif direction=='usd_per_foreign':y=amount*rate;unit='usd';rule='foreign_amount * usd_per_foreign'
                else:raise ValueError('exchange-rate orientation must be explicit')
            else:raise ValueError('unsupported Treasury transform')
            if not y.is_finite():raise ValueError('nonfinite transformed output')
            digits=inputs.get('decimals')
            if digits is None:ans=format(y,'f').rstrip('0').rstrip('.') if '.' in format(y,'f') else format(y,'f')
            else:
                if type(digits) is not int or not 0<=digits<=18:raise ValueError('decimals must be 0..18')
                ans=format(y.quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_UP),f'.{digits}f')
            if ans in ('-0',''):ans='0'
            return {'status':'ok','outputs':{
                'value':str(y),'answer':ans,'unit':unit,'formula':rule,
                'proof_scope':'local_transform_only',
                'note':'Input numbers and quote/currency convention must be grounded in a real source table.'}}
    except (ValueError,TypeError,KeyError,ArithmeticError) as exc:
        return {'status':'needs_input','outputs':{},'detail':str(exc)}
